steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      issue(identifier: \"ENG-42\") {
        id
        identifier
        title
        comments(first: 50) {
          nodes {
            id
            body
            user {
              id
              name
              email
            }
          }
        }
      }
    }
  }'
